@Override
public UserSocial getByUnionid(String unionid) {
    if (StrUtil.isBlank(unionid)) {
        return null;
    }
    return getOne(new LambdaQueryWrapper<UserSocial>()
            .eq(UserSocial::getUnionid, unionid));
}

