private void setRedisValue(String key, Object value, int ttl) {
    if (ttl != -1) {
        redisTemplate.opsForValue().set(key, value, ttl, TimeUnit.SECONDS);
    } else {
        redisTemplate.opsForValue().set(key, value); // ttl=-1时永不过期
    }
}

