public static String getTsTypeByJavaType(String javaType) {
    if (javaType == null) {
        return "any";
    }
    for (JavaTypeEnum javaTypeEnum : JavaTypeEnum.values()) {
        if (javaTypeEnum.getJavaType().equals(javaType)) {
            return javaTypeEnum.getTsType();
        }
    }
    return "any";
}

