            DataPermission annotation = method.getAnnotation(DataPermission.class);
            // 判断当前执行的方法是否有权限注解，如果没有注解直接返回
            if (annotation == null) {
                return where;
            }
            // 使用并集策略过滤
            return dataScopeFilterWithUnion(mappedStatementId, annotation, dataScopes, where);
        }
    }
    return where;
}

