        // 安全上下文清除保障（防止上下文残留）
        SecurityContextHolder.clearContext();
        ResponseWriter.writeError(response, ResultCode.ACCESS_TOKEN_INVALID);
        return;
    }

    // 继续后续过滤器链执行
    filterChain.doFilter(request, response);
}

